const baseUrl = String.fromEnvironment('API_URL', defaultValue: 'http://10.0.2.2:4000/api/v1');
void main() => runApp(const Ceramica());
class Ceramica extends StatelessWidget {
 const Ceramica({super.key});
 @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner:false,title:'CERAMICA',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff215a50)),useMaterial3:true,scaffoldBackgroundColor:const Color(0xfff8f7f3)),darkTheme:ThemeData.dark(useMaterial3:true),home:const Showroom());
}
class Api {
 final storage = const FlutterSecureStorage();
 Future<dynamic> call(String path,{Map<String,dynamic>? body}) async {
  final token=await storage.read(key:'session');
  final headers={'Content-Type':'application/json',if(token!=null)'Authorization':'Bearer $token'};
  final uri=Uri.parse('$baseUrl/$path');
  final response=body==null?await http.get(uri,headers:headers).timeout(const Duration(seconds:20)):await http.post(uri,headers:headers,body:jsonEncode(body)).timeout(const Duration(seconds:20));
  final data=jsonDecode(response.body);
  if(response.statusCode>=400) throw Exception(data['message'].toString());
  return data;
 }
}
class Showroom extends StatefulWidget {const Showroom({super.key});@override State<Showroom> createState()=>_ShowroomState();}
