e5e2d9):const Color(0xff606861),alignment:Alignment.bottomLeft,padding:const EdgeInsets.all(16),child:Text(p['brand']['name'],style:const TextStyle(letterSpacing:3,color:Colors.white))),Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p['name'],style:const TextStyle(fontSize:20,fontFamily:'serif')),Text('${p['size']} · ${p['surface']}'),const SizedBox(height:14),Text('${p['price']} TL/m² + KDV',style:const TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('${p['availableBoxes']} koli · ${p['boxArea']} m²/koli'),const SizedBox(height:10),const Row(children:[Text('İncele ve metraj hesapla'),Spacer(),Icon(Icons.arrow_forward,size:18)])]))])))])));
}
class ProductDetail extends StatefulWidget{final dynamic product;final Api api;const ProductDetail({super.key,required this.product,required this.api});@override State<ProductDetail> createState()=>_ProductDetailState();}
class _ProductDetailState extends State<ProductDetail>{final area=TextEditingController(text:'47');final waste=TextEditingController(text:'10');dynamic result;String? error;bool busy=false;
 @override void dispose(){area.dispose();waste.dispose();super.dispose();}
 Future<void> calculate()async{setState((){busy=true;error=null;});try{final d=await widget.api.call('calculator',body:{'productId':widget.product['id'],'area':double.parse(area.text.replaceAll(',','.')),'waste':double.parse(waste.text.replaceAll(',','.'))});if(mounted)setState(()=>result=d);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
