}
class Login extends StatefulWidget{final Api api;const Login({super.key,required this.api});@override State<Login>createState()=>_LoginState();}
class _LoginState extends State<Login>{final email=TextEditingController();final password=TextEditingController();String? error;bool busy=false;@override void dispose(){email.dispose();password.dispose();super.dispose();}
 Future<void> login()async{setState((){busy=true;error=null;});try{final d=await widget.api.call('auth/login',body:{'email':email.text,'password':password.text});await widget.api.storage.write(key:'session',value:d['token']);if(mounted){Navigator.pop(context);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Oturum açıldı')));}}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Oturum aç')),body:ListView(padding:const EdgeInsets.all(24),children:[TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'E-posta')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Parola')),const SizedBox(height:24),FilledButton(onPressed:busy?null:login,child:const Text('Oturum aç')),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red))]));
}
class Orders extends StatelessWidget{final Api api;const Orders({super.key,required this.api});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Siparişlerim')),body:FutureBuilder<dynamic>(future:api.call('orders'),builder:(context,snapshot){if(snapshot.hasError)return Padding(padding:const EdgeInsets.all(24),child:Text('Siparişler alınamadı. Oturumunuzu kontrol edin.\n${snapshot.error}'));if(!snapshot.hasData)return const Center(child:CircularProgressIndicator());final list=snapshot.data as List;if(list.isEmpty)return const Center(child:Text('Henüz siparişiniz bulunmuyor.'));return ListView(children:list.map((o)=>ListTile(title:Text(o['number']),subtitle:Text(o['status']),trailing:Text('${o['total']} TL'))).toList());}));}
